{"path": "app.js", "offset_utf8_bytes": 57383, "content": "/* ---------- reviews modal ---------- */
  var REVIEW_SORTS = [['most_recent', 'Most recent'], ['oldest', 'Oldest'], ['highest', 'Highest rated'],
    ['lowest', 'Lowest rated'], ['most_helpful', 'Most helpful']];

  function reviewList() {
    var arr = REVIEWS.filter(function (r) { return !UI.reviewFilter || r.r === UI.reviewFilter; });
    var s = UI.reviewSort;
    if (s === 'oldest') arr.sort(function (a, b) { return new Date(a.d.replace(/\//g, '/')) - new Date(b.d.replace(/\//g, '/')); });
    else if (s === 'highest') arr.sort(function (a, b) { return b.r - a.r; });
    else if (s === 'lowest') arr.sort(function (a, b) { return a.r - b.r; });
    else if (s === 'most_helpful') arr.sort(function (a, b) { return b.h - a.h; });
    else arr.sort(function (a, b) { return new Date(b.d) - new Date(a.d); });
    return arr;
  }
  function starRow(r, size) {
    var s = '<span class="stars" style="font-size:' + (size || 14) + 'px">';
    for (var i = 1; i <= 5; i++) s += '<span class="' + (i <= Math.round(r) ? '' : 'off') + '">\u2605</span>';
    return s + '</span>';
  }

  function reviewsModal(o) {
    var p = P(o.id) || P('29612189');
    var hist = REVIEW_DIST.map(function (d) {
      var w = Math.round(d[1] / 54 * 100);
      if (w < 3) w = 3;
      return '<div class="rbar"><span>' + d[0] + ' \u2605</span><span class="track"><span class="fill" style="width:' + w + '%"></span></span><span>' + d[1] + '</span></div>';
    }).join('');
    var subs = REVIEW_SUB.map(function (s) {
      var dots = '';
      for (var i = 1; i <= 5; i++) dots += '<i class="' + (i <= Math.round(s[1]) ? '' : 'off') + '"></i>';
      return '<div class="subrow"><span>' + esc(s[0]) + '</span><span style="display:flex;gap:14px;align-items:center">' +
        '<span class="dots">' + dots + '</span><b>' + s[1].toFixed(1) + '</b></span></div>';
    }).join('');

    var filterMenu = UI.reviewFilterOpen ? '<div class="sortmenu" style="left:0;top:58px">' +
      '<label class="' + (!UI.reviewFilter ? 'on' : '') + '" data-act="review-filter-set" data-star="0"><span class="dot"></span><span>All ratings</span></label>' +
      [5, 4, 3, 2, 1].map(function (n) {
        return '<label class="' + (UI.reviewFilter === n ? 'on' : '') + '" data-act="review-filter-set" data-star="' + n + '"><span class="dot"></span><span>' + n + ' star' + (n > 1 ? 's' : '') + '</span></label>';
      }).join('') + '</div>' : '';
    var sortMenu = UI.reviewSortOpen ? '<div class="sortmenu">' +
      REVIEW_SORTS.map(function (s) {
        return '<label class="' + (UI.reviewSort === s[0] ? 'on' : '') + '" data-act="review-sort-set" data-sort="' + s[0] + '"><span class="dot"></span><span>' + s[1] + '</span></label>';
      }).join('') + '</div>' : '';

    var topics = '<div class="topics"><span class="t">Show all</span>' + REVIEW_TOPICS.map(function (t) {
      return '<span class="t alt">' + esc(t) + '</span>';
    }).join('') + '</div>';

    var summary = UI.reviewSummary ?
      '<div class="summary"><h4>Reviews summary ' + I.layers +
      '<span style="flex:1"></span><a style="font-size:13px;font-weight:400;text-decoration:underline" data-act="toggle-summary">Hide summary</a></h4>' +
      '<p>' + esc(REVIEW_SUMMARY) + '</p>' +
      '<p style="font-size:12px;color:#767676;margin-top:10px">AI-generated summary of actual customer reviews.</p>' +
      '<div class="sf"><span>Helpful?</span><a>\uD83D\uDC4D</a><a>\uD83D\uDC4E</a></div></div>' : '';

    var list = reviewList().map(function (r) {
      return '<div class="review"><div class="hd">' + starRow(r.r) +
        '<span style="font-size:13px;color:#484848">' + esc(r.d) + '</span></div>' +
        '<h4>' + esc(r.t) + '</h4><p>' + esc(r.b) + '</p>' +
        '<div class="ft"><span class="who">' + esc(r.a) + '</span><span style="flex:1"></span>' +
        '<a style="text-decoration:underline;font-weight:700" data-act="report">Report</a>' +
        '<button class="rep" data-act="helpful">Helpful? (' + r.h + ')</button></div>' +
        (r.resp ? '<div class="resp"><b>Response from IKEA:</b> ' + esc(r.rd) +
          '<div style="margin-top:6px">' + esc(r.resp) + '</div></div>' : '') +
        '</div>';
    }).join('');

    var formPanel = '';
    if (UI.reviewForm === 'open' || UI.reviewForm === 'done') {
      formPanel = '<div class="summary" style="background:#fff;border:1px solid var(--line2)">' +
        '<h4>Write a review</h4>' +
        (UI.reviewForm === 'done' ? '<p style="color:var(--green);font-weight:700;margin-bottom:10px">Thank you! Your review has been submitted.</p>' : '') +
        '<div style="display:flex;gap:16px;margin-bottom:10px"><span style="font-size:13px;font-weight:700">Your rating</span>' +
        '<span style="display:flex;gap:6px">' + [1, 2, 3, 4, 5].map(function (n) {
          return '<button data-act="form-star" data-star="' + n + '" class="' + (UI.reviewFormStar >= n ? '' : 'off') + '" style="color:' + (UI.reviewFormStar >= n ? '#111' : '#ccc') + ';font-size:20px">\u2605</button>';
        }).join('') + '</span></div>' +
        '<div style="display:flex;flex-direction:column;gap:10px;max-width:640px">' +
        '<input id="rvTitle" placeholder="Title of your review" value="' + esc(UI.reviewFormTitle || '') + '" style="height:44px;border:1px solid var(--line);border-radius:4px;padding:0 12px;font-size:14px;outline:0">' +
        '<textarea id="rvBody" rows="4" placeholder="Tell us what you think" style="border:1px solid var(--line);border-radius:4px;padding:10px 12px;font-size:14px;outline:0;font-family:inherit">' + esc(UI.reviewFormBody || '') + '</textarea>' +
        '<input id="rvName" placeholder="Your name" value="' + esc(UI.reviewFormName || '') + '" style="height:44px;border:1px solid var(--line);border-radius:4px;padding:0 12px;font-size:14px;outline:0">' +
        '<div style="display:flex;gap:12px"><button class="btn blue" data-act="submit-review">Submit review</button>' +
        '<button class="btn ghost" data-act="close-review-form">Cancel</button></div></div></div>';
    }

    return ovWrap('<div class="modal" style="max-width:1160px;width:calc(100% - 60px);height:88vh;position:relative">' +
      '<div class="mh" style="position:absolute;right:6px;top:6px;z-index:4">' + closeIcon() + '</div>' +
      '<div class="mb" style="padding:0;flex:1;overflow:hidden;display:flex">' +
        '<div class="reviewswrap" style="flex:1;height:100%">' +
          '<div class="rl" style="overflow:auto;height:100%">' +
            '<div class="avg">' + p.rating.toFixed(1) + '</div>' +
            '<span class="stars" style="text-align:center;font-size:22px;display:block">' +
              [1, 2, 3, 4, 5].map(function (i) { return '<span class="' + (i <= Math.round(p.rating) ? '' : 'off') + '">\u2605</span>'; }).join('') + '</span>' +
            '<div class="based">Based on ' + p.review_count + ' reviews</div>' +
            hist + subs +
            '<button class="btn ghost full" style="margin-top:24px" data-act="write-review">Write a review</button>' +
          '</div>' +
          '<div class="rr">' +
            '<h2>Customer reviews</h2>' +
            '<div class="rrf">' +
              '<button class="b' + (UI.reviewFilterOpen ? ' on' : '') + '" data-act="review-filter">' + I.filter + ' Filter</button>' +
              '<button class="b' + (UI.reviewSortOpen ? ' on' : '') + '" data-act="review-sort">' + I.sorti + ' Sort by</button>' +
              filterMenu + sortMenu +
            '</div>' +
            '<div class="tabs2">' +
              '<button class="' + (UI.reviewCountry === 'us' ? 'on' : '') + '" data-act="review-country" data-c="us">United States</button>' +
              '<button class="' + (UI.reviewCountry === 'other' ? 'on' : '') + '" data-act="review-country" data-c="other">Other countries</button>' +
            '</div>' +
            formPanel + summary + topics +
            (UI.reviewCountry === 'other'
              ? '<p style="padding:30px 0">Reviews from other countries are not available in this recording.</p>'
              : list) +
          '</div>' +
        '</div>' +
      '</div></div>', true);
  }

  /* ---------- toast ---------- */
  function toast(msg, undoLabel, undoFn) {
    var el = document.createElement('div');
    el.className = 'toast';
    el.innerHTML = '<span class="txt">' + msg + '</span>' +
      (undoLabel ? '<button class="undo">' + undoLabel + '</button>' : '') +
      '<button class="x" aria-label="Close">' + I.close + '</button>';
    toastWrap.appendChild(el);
    var timer = setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 7000);
    if (undoLabel && undoFn) {
      el.querySelector('.undo').addEventListener('click', function () {
        clearTimeout(timer);
        undoFn();
        if (el.parentNode) el.parentNode.removeChild(el);
      });
    }
    el.querySelector('.x').addEventListener('click', function () {
      clearTimeout(timer);
      if (el.parentNode) el.parentNode.removeChild(el);
    });
  }

  /* ============================================================ RENDER */
  function render() {
    var route = UI.route;
    var html = renderTop() + renderHeader(route);
    if (UI.meganav && route.name === 'home') html += renderMeganav();
    if (route.name === 'home') html += renderHome();
    else if (route.name === 'search') html += renderSearch(route);
    else if (route.name === 'compare') html += renderCompare();
    else if (route.name === 'bag') html += renderBag();
    else if (route.name === 'product') html += renderProduct(route.id);
    if (!ST.cookieHidden) html += renderCookie();
    app.innerHTML = html;
    app.className = UI.meganav ? 'mnav-open' : '';
    modals.innerHTML = renderOverlays();
    updateSug();
  }

  function updateSug() {
    var inp = document.getElementById('searchInput');
    var box = document.getElementById('sugBox');
    if (!inp || !box) return;
    var norm = (inp.value || '').trim().toLowerCase();
    if (!norm || !UI.searchOpen) { box.classList.remove('on'); return; }
    var matches = SUGGESTIONS.filter(function (s) {
      return s.toLowerCase().indexOf(norm) >= 0 && s.toLowerCase() !== norm;
    }).slice(0, 7);
    var rows = '<a data-act="do-search-now"><span>' + I.search + '</span><span>' + esc(inp.value) + '</span></a>';
    rows += matches.map(function (s) {
      return '<a data-act="sug" data-q="' + esc(s) + '"><span>' + I.search + '</span><span>' + esc(s) + '</span></a>';
    }).join('');
    box.innerHTML = rows;
    box.classList.add('on');
  }", "file_complete": false, "project_complete": false}
